<template>
  <section class="container py-4 management-page members-page">
    <header class="management-heading"><div><p class="management-eyebrow">{{ auth.user?.church?.name }}</p><h1>{{ tr('Miembros','Members') }}</h1><p>{{ tr('Define la información de tu iglesia, registra miembros o importa tu plantilla CSV.','Define your church’s information, register members or import your CSV template.') }}</p></div></header>
    <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p>
    <p v-if="loading" role="status">{{ tr('Cargando…','Loading…') }}</p>
    <template v-else>
      <details v-write="'members.manage'" class="management-surface member-panel" :open="!template" @toggle="templateOpen=$event.target.open">
        <summary>{{ tr('Configurar plantilla','Configure template') }} <span>{{ template ? `${tr('Versión','Version')} ${template.version}` : tr('Empieza aquí','Start here') }}</span></summary>
        <p>{{ tr('Nombre, correo y teléfono siempre son obligatorios. Agrega los demás datos que necesites. Guarda antes de descargar el CSV. Al cambiar la plantilla, descarga una copia nueva; los datos anteriores se conservan.','Name, email and phone are always required. Add any other information you need. Save before downloading the CSV. After changing the template, download a new copy; previous data is retained.') }}</p>
        <div class="fixed-fields"><span>{{ tr('Nombre · Texto · Obligatorio','Name · Text · Required') }}</span><span>{{ tr('Correo · Email · Obligatorio','Email · Email · Required') }}</span><span>{{ tr('Teléfono · Obligatorio','Phone · Required') }}</span></div>
        <fieldset :disabled="busy || !auth.can('members.manage')">
          <article v-for="(field,index) in draftFields" :key="field.id" class="member-field">
            <div class="member-field-heading"><strong>{{ index+1 }} · {{ typeLabel(field.type) }}</strong><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-secondary" :disabled="index===0" :aria-label="tr('Subir','Move up')" @click="move(index,-1)">↑</button><button class="btn btn-sm btn-outline-secondary" :disabled="index===draftFields.length-1" :aria-label="tr('Bajar','Move down')" @click="move(index,1)">↓</button><button class="btn btn-sm btn-outline-secondary" @click="draftFields.splice(index,1)">{{ tr('Quitar','Remove') }}</button></div></div>
            <label>{{ tr('Nombre del campo','Field label') }}<input v-model="field.label" class="form-control" maxlength="150" /></label>
            <label v-if="field.type==='select'">{{ tr('Opciones, una por línea','Options, one per line') }}<textarea class="form-control" :value="field.options.join('\n')" @input="field.options=$event.target.value.split('\n')"></textarea></label>
            <label class="check"><input type="checkbox" v-model="field.required" />{{ tr('Obligatorio','Required') }}</label>
          </article>
          <div class="add-member-field"><label>{{ tr('Agregar campo','Add field') }}<select v-model="newType" class="form-select"><option v-for="type in types" :key="type" :value="type">{{ typeLabel(type) }}</option></select></label><button type="button" class="creation-plus" :disabled="draftFields.length>=40" @click="addField" :aria-label="tr('Agregar campo','Add field')" :title="tr('Agregar campo','Add field')"><span aria-hidden="true">+</span></button></div>
          <div class="d-flex flex-wrap gap-2"><button class="btn btn-primary" @click="saveTemplate">{{ tr('Guardar plantilla','Save template') }}</button><button class="btn btn-outline-secondary" @click="resetTemplate">{{ tr('Descartar cambios','Discard changes') }}</button></div>
        </fieldset>
      </details>
      <section v-if="template" class="management-surface member-panel">
        <h2>{{ tr('Carga masiva CSV','Bulk CSV import') }}</h2>
        <ol><li>{{ tr('Descarga la plantilla guardada. Conserva la primera fila de encabezados sin cambios.','Download the saved template. Keep the first header row unchanged.') }}</li><li>{{ tr('Agrega una persona por fila. Fechas: AAAA-MM-DD. Casillas: sí/no o true/false. Guarda teléfonos como texto para conservar + y ceros iniciales.','Add one person per row. Dates: YYYY-MM-DD. Checkboxes: yes/no or true/false. Store phone numbers as text to preserve + and leading zeroes.') }}</li><li>{{ tr('Carga el CSV UTF-8 y revisa antes de importar. Máximo 1,000 personas y 2 MB. Correos duplicados se rechazan; no se reemplazan registros.','Upload the UTF-8 CSV and review before importing. Maximum 1,000 people and 2 MB. Duplicate emails are rejected; existing records are not overwritten.') }}</li></ol>
        <details v-if="template.fields.some(f=>f.type==='select')"><summary>{{ tr('Opciones permitidas','Allowed choices') }}</summary><p v-for="field in template.fields.filter(f=>f.type==='select')" :key="field.id"><strong>{{ field.label }}:</strong> {{ field.options.join(' · ') }}</p></details>
        <div class="member-toolbar"><button class="btn btn-outline-primary" :disabled="busy" @click="downloadTemplate">{{ tr('Descargar plantilla CSV','Download CSV template') }}</button><label v-write="'members.manage'">{{ tr('Archivo CSV','CSV file') }}<input ref="fileInput" type="file" accept=".csv,text/csv" :disabled="busy" class="form-control" @change="selectFile" /></label><button v-write="'members.manage'" class="btn btn-outline-primary" :disabled="busy || !importFile" @click="previewImport">{{ tr('Validar archivo','Validate file') }}</button></div>
        <div v-if="importPreview" class="import-preview"><h3>{{ importPreview.count }} {{ tr('miembros listos para importar','members ready to import') }}</h3><p>{{ tr('Vista previa de las primeras cinco personas:','Preview of the first five people:') }}</p><ul><li v-for="person in importPreview.sample" :key="person.email">{{ person.name }} · {{ person.email }} · {{ person.phone }}</li></ul><button class="btn btn-primary" :disabled="busy" @click="commitImport">{{ tr('Importar miembros','Import members') }}</button></div>
      </section>
      <section class="management-surface member-panel">
        <div class="member-toolbar"><div><div class="member-list-heading"><h2>{{ tr('Lista de miembros','Member list') }}</h2><button v-write="'members.manage'" v-if="auth.can('members.manage')" type="button" class="btn member-add-icon" :disabled="!template || busy" :aria-label="editing && !editingId ? tr('Cancelar','Cancel') : tr('Agregar miembro','Add member')" :title="editing && !editingId ? tr('Cancelar','Cancel') : tr('Agregar miembro','Add member')" :aria-expanded="editing && !editingId" @click="editing && !editingId ? editing=false : editMember()"><span v-if="!(editing && !editingId)" aria-hidden="true">+</span><span v-else class="creation-cancel-label">{{ tr('Cancelar','Cancel') }}</span></button></div><p>{{ members.length }} {{ tr('registros','records') }}</p></div><label><span class="visually-hidden">{{ tr('Buscar','Search') }}</span><input v-model="search" type="search" class="form-control" :placeholder="tr('Nombre, correo, teléfono…','Name, email, phone…')" /></label></div>
        <p v-if="!template">{{ tr('Guarda la plantilla para comenzar. Puedes usar solo los tres campos estándar.','Save the template to begin. You can use only the three standard fields.') }}</p>
        <p v-else-if="!filteredMembers.length">{{ tr('No hay miembros que mostrar.','No members to display.') }}</p>
        <article v-for="member in filteredMembers" :key="member.id" class="member-record">
          <div class="member-identity"><h3>{{ member.name }}</h3><p>{{ member.email }}</p><p>{{ member.phone }}</p></div>
          <div v-if="auth.can('members.manage') || Object.keys(member.data||{}).length" class="member-actions">
            <span class="member-actions-label">{{ tr('Acciones','Actions') }}</span>
            <div class="member-action-buttons">
              <button v-write="'members.manage'" v-if="auth.can('members.manage')" class="btn btn-outline-secondary" :disabled="busy" :aria-expanded="editing && editingId===member.id" @click="toggleMemberEditor(member)">{{ editing && editingId===member.id ? tr('Cancelar','Cancel') : tr('Editar','Edit') }}</button>
              <button v-if="Object.keys(member.data||{}).length" type="button" class="btn btn-outline-secondary" :aria-expanded="!!expandedMembers[member.id]" :aria-controls="`member-details-${member.id}`" @click="expandedMembers[member.id]=!expandedMembers[member.id]">{{ expandedMembers[member.id] ? tr('Cerrar datos adicionales','Close additional information') : tr('Ver datos adicionales','View additional information') }}</button>
            </div>
          </div>
          <div v-if="expandedMembers[member.id]" :id="`member-details-${member.id}`" class="member-additional"><dl><div v-for="field in historicalFields.filter(f=>Object.hasOwn(member.data||{},f.id))" :key="field.id"><dt>{{ field.label }}</dt><dd>{{ displayValue(member.data[field.id]) }}</dd></div></dl></div>
        </article>
      </section>
      <section v-if="editing" ref="editor" class="management-surface member-panel"><h2>{{ editingId ? tr('Editar miembro','Edit member') : tr('Nuevo miembro','New member') }}</h2><p>{{ tr('Los campos con * son obligatorios.','Fields marked * are required.') }}</p><form @submit.prevent="saveMember"><fieldset :disabled="busy || !auth.can('members.manage')"><div class="member-inputs"><label>{{ tr('Nombre','Name') }} *<input v-model="memberDraft.name" class="form-control" required maxlength="255" /></label><label>{{ tr('Correo','Email') }} *<input v-model="memberDraft.email" type="email" class="form-control" required maxlength="255" /></label><label>{{ tr('Teléfono','Phone') }} *<input v-model="memberDraft.phone" type="tel" class="form-control" required maxlength="50" /></label>
        <label v-for="field in template.fields" :key="field.id" :class="{'check':field.type==='checkbox'}"><template v-if="field.type==='checkbox'"><select class="form-select" v-model="memberDraft.data[field.id]" :required="field.required"><option :value="null">—</option><option :value="true">{{ tr('Sí','Yes') }}</option><option :value="false">No</option></select>{{ field.label }}{{ field.required?' *':'' }}</template><template v-else>{{ field.label }}{{ field.required?' *':'' }}<textarea v-if="field.type==='textarea'" v-model="memberDraft.data[field.id]" class="form-control" :required="field.required" maxlength="5000"></textarea><select v-else-if="field.type==='select'" v-model="memberDraft.data[field.id]" class="form-select" :required="field.required"><option :value="null">—</option><option v-for="option in field.options" :key="option" :value="option">{{ option }}</option></select><input v-else v-model="memberDraft.data[field.id]" :type="inputType(field.type)" class="form-control" :required="field.required" :max="field.type==='dob'?today:undefined" :step="field.type==='number'?'any':undefined" :maxlength="field.type==='text'?500:255" /></template></label></div>
        <p v-if="memberError" class="alert alert-danger" role="alert">{{ memberError }}</p><div class="d-flex gap-2 mt-3"><button class="btn btn-primary">{{ tr('Guardar miembro','Save member') }}</button><button type="button" class="btn btn-outline-secondary" @click="editing=false">{{ tr('Cancelar','Cancel') }}</button></div></fieldset></form></section>
    </template>
  </section>
</template>
<script setup>
import { computed, ref, onMounted, nextTick } from 'vue'
import { useAuthStore } from '../stores/authStore'
import { useUiStore } from '../stores/uiStore'
import { membersApi } from '../services/membersApi'
import '../styles/clerk-management.css'
const auth=useAuthStore(),ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),template=ref(null),members=ref([]),historicalFields=ref([]),draftFields=ref([]),newType=ref('text'),templateOpen=ref(false)
const expandedMembers=ref({})
const search=ref(''),importFile=ref(null),importPreview=ref(null),fileInput=ref(null),editing=ref(false),editingId=ref(null),memberDraft=ref({}),memberError=ref(''),editor=ref(null)
const types=['text','textarea','email','phone','dob','date','number','checkbox','select']
const typeLabel=type=>({text:tr('Texto corto','Short text'),textarea:tr('Texto largo','Long text'),email:tr('Correo','Email'),phone:tr('Teléfono','Phone'),dob:tr('Fecha de nacimiento','Date of birth'),date:tr('Fecha','Date'),number:tr('Número','Number'),checkbox:tr('Sí / No','Yes / No'),select:tr('Lista de opciones','Dropdown')})[type]
const inputType=type=>({dob:'date',phone:'tel'})[type]||type
const today=new Date().toLocaleDateString('en-CA')
const displayValue=value=>value===true?tr('Sí','Yes'):value===false?'No':value??'—'
const filteredMembers=computed(()=>members.value.filter(m=>[m.name,m.email,m.phone,...Object.values(m.data||{})].join(' ').toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))
const message=e=>Object.entries(e.response?.data?.errors||{}).map(([key,values])=>`${key}: ${values.join(' ')}`).join('\n')||e.response?.data?.message||tr('No se pudo completar la operación.','Unable to complete the operation.')
function resetTemplate(){draftFields.value=structuredClone(template.value?JSON.parse(JSON.stringify(template.value.fields)):[])}
async function load(){const result=await membersApi.list();template.value=result.template;members.value=result.members;historicalFields.value=result.historical_fields;resetTemplate()}
onMounted(async()=>{try{await load()}catch(e){error.value=message(e)}finally{loading.value=false}})
function addField(){draftFields.value.push({id:crypto.randomUUID(),type:newType.value,label:'',required:false,options:[]})}
function move(index,offset){const field=draftFields.value.splice(index,1)[0];draftFields.value.splice(index+offset,0,field)}
async function saveTemplate(){busy.value=true;error.value='';notice.value='';try{template.value=await membersApi.template({base_version:template.value?.version||0,fields:draftFields.value.map(f=>({...f,label:f.label.trim(),options:f.type==='select'?f.options.map(o=>o.trim()).filter(Boolean):[]}))});importPreview.value=null;importFile.value=null;if(fileInput.value)fileInput.value.value='';editing.value=false;await load();notice.value=tr('Plantilla guardada. Ya puedes descargarla o agregar miembros.','Template saved. You can now download it or add members.')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function downloadTemplate(){busy.value=true;error.value='';try{const blob=await membersApi.download();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`members-template-v${template.value.version}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=message(e)}finally{busy.value=false}}
function selectFile(event){importFile.value=event.target.files?.[0]||null;importPreview.value=null;error.value=''}
async function previewImport(){busy.value=true;error.value='';notice.value='';importPreview.value=null;try{importPreview.value=await membersApi.import(importFile.value,true)}catch(e){error.value=message(e)}finally{busy.value=false}}
async function commitImport(){busy.value=true;error.value='';try{const result=await membersApi.import(importFile.value,false);importPreview.value=null;importFile.value=null;if(fileInput.value)fileInput.value.value='';await load();notice.value=`${result.created} ${tr('miembros importados.','members imported.')}`}catch(e){error.value=message(e);importPreview.value=null}finally{busy.value=false}}
function toggleMemberEditor(member){if(editing.value && editingId.value===member.id){editing.value=false;editingId.value=null;memberDraft.value={};memberError.value='';return}editMember(member)}
async function editMember(member=null){editingId.value=member?.id||null;memberError.value='';memberDraft.value={template_id:template.value.id,name:member?.name||'',email:member?.email||'',phone:member?.phone||'',data:Object.fromEntries(template.value.fields.map(f=>[f.id,member?.data?.[f.id]??null]))};editing.value=true;await nextTick();editor.value?.scrollIntoView({behavior:'smooth',block:'start'})}
async function saveMember(){busy.value=true;memberError.value='';try{await membersApi.save(editingId.value,memberDraft.value);editing.value=false;await load();notice.value=tr('Miembro guardado.','Member saved.')}catch(e){memberError.value=message(e)}finally{busy.value=false}}
</script>
<style scoped>
.members-page{min-width:0}.member-list-heading{display:flex;align-items:center;gap:10px;margin-bottom:8px}.member-list-heading h2{margin:0}.members-page .member-add-icon{display:inline-flex;align-items:center;justify-content:center;flex:none;width:32px;height:32px;padding:0;border:0;background:transparent;color:#1f6f5c;border-radius:8px;font-size:24px;line-height:1}.members-page .member-add-icon:has(.creation-cancel-label){width:auto;font-size:13px}.creation-cancel-label{font-size:13px}.member-add-icon:focus-visible{outline:3px solid #85b9a6;outline-offset:3px}.member-panel{padding:20px;margin:20px 0}.member-panel summary{cursor:pointer;font-weight:500;color:#244f3c}.member-panel summary span{font-size:12px;color:#52645a;margin-left:12px}.member-panel h2{font-size:18px}.member-panel h3{font-size:15px}.member-panel p,.member-panel ol{color:#52645a;font-size:13px}.member-panel label{display:block;font-size:13px}.member-panel .form-control,.member-panel .form-select{margin-top:5px;font-size:13px}.fixed-fields{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.fixed-fields span{background:#edf5f0;color:#28543e;padding:8px 12px;border-radius:6px;font-size:12px}.member-field{border:1px solid #dce5df;border-radius:8px;padding:16px;margin:12px 0;display:grid;gap:12px}.member-field-heading,.member-toolbar,.add-member-field{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.add-member-field{background:#edf5f0;border:2px dashed #8da998;border-radius:8px;padding:16px;margin:18px 0}.check{display:flex!important;gap:8px;align-items:center}.check input{width:16px;height:16px}.member-record{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px;padding:18px;margin-top:12px;border:1px solid #dce5df;border-radius:8px;background:#fff;overflow-wrap:anywhere}.member-identity{align-self:center;min-width:0}.member-identity h3{margin:0 0 8px}.member-actions{border-left:1px solid #dce5df;padding-left:20px;max-width:340px}.member-actions-label{display:block;font-size:11px;color:#66776d;margin-bottom:8px}.member-action-buttons{display:flex;gap:8px;flex-wrap:wrap}.member-action-buttons .btn{margin:0;font-size:13px}.member-additional{grid-column:1/-1;border-top:1px solid #dce5df;padding-top:16px}.member-additional dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:0}.member-additional dt{font-size:12px;color:#66776d;font-weight:500}.member-additional dd{font-size:13px;margin:4px 0 0}.member-record p{margin:4px 0}.member-record details{margin-top:12px}.member-record dd{white-space:pre-wrap}.member-inputs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.member-inputs label{min-width:0}.member-inputs .check select{max-width:100px}.members-page .alert{white-space:pre-wrap;overflow-wrap:anywhere}.import-preview{background:#edf5f0;padding:16px;border-radius:8px;margin-top:16px;overflow-wrap:anywhere}.members-page .btn{width:auto;white-space:normal}.members-page .btn-outline-primary{color:#1f6f5c;background:#fff;border-color:#1f6f5c}.members-page .btn-outline-primary:hover{color:#fff;background:#1f6f5c}.members-page .btn-outline-secondary{color:#52645a;background:#fff;border-color:#8da998}.members-page .btn-primary{background:#1f6f5c;color:#fff;border-color:#1f6f5c}.members-page .btn:disabled{color:#657269;background:#edf1ee;border-color:#c5d0c9;opacity:1}@media(max-width:650px){.member-actions{max-width:none;border-left:0;border-top:1px solid #dce5df;padding:12px 0 0}.member-action-buttons{display:grid;grid-template-columns:1fr 2fr}.member-action-buttons .btn{width:100%}.member-additional dl{grid-template-columns:1fr}.member-panel{padding:14px}.member-inputs,.member-record{grid-template-columns:1fr}.member-toolbar>label,.add-member-field>label{width:100%}.member-toolbar input{max-width:100%}.member-field-heading{align-items:flex-start}}
</style>
